import { RoosterBeak } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface RoosterOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Rooster (`公雞`):
 * - Aggressive mid-tier bird with medium sensing range (6 tiles), higher AGI/STR, and spur attacks.
 * - Cannot open or close doors (`canOpenDoors = false`).
 */
export class Rooster extends Enemy {
  constructor(options: RoosterOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_rooster',
      name: 'Rooster',
      position: options.position,
      spriteKey: 'enemy_rooster',
      level: 2,
      xpReward: 25,
      movementType: 'walking',
      sensingRange: 6,
      canOpenDoors: false,
      scoreValue: 60,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 200,
      meatWeight: 2.0,
      soulDropId: 'fledgling',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      trophyDrops: [
        {
          itemTypeId: 'rooster_beak',
          chance: 0.25,
          create: ({ id, position }) => new RoosterBeak({ id, position }),
        },
      ],
      attributes: {
        str: 8,
        con: 7,
        int: 3,
        wis: 4,
        agi: 13,
        luk: 8,
      },
    });
  }
}
