  /**
   * 32x32 shimmering arcane Victory Portal ('O') on the final dungeon layer.
   */
  private createPortalBitmap(): SpriteBitmap {
    const bmp = this.createFloorBitmap();
    const data = bmp.data;
    const archDark: RGBA = [36, 26, 58, 255];
    const archRunic: RGBA = [148, 126, 214, 255];
    const outerVortex: RGBA = [99, 102, 241, 245];
    const midVortex: RGBA = [56, 189, 248, 255];
    const coreGlow: RGBA = [224, 242, 254, 255];

    for (let y = 4; y <= 27; y++) {
      for (let x = 6; x <= 25; x++) {
        const dx = (x - 15.5) / 8.5;
        const dy = (y - 15.5) / 10.5;
        const r = dx * dx + dy * dy;
        if (r <= 1.05 && r > 0.72) {
          setPixel(data, x, y, (x + y) % 3 === 0 ? archRunic : archDark);
        } else if (r <= 0.72 && r > 0.4) {
          setPixel(data, x, y, outerVortex);
        } else if (r <= 0.4 && r > 0.14) {
          setPixel(data, x, y, midVortex);
        } else if (r <= 0.14) {
          setPixel(data, x, y, coreGlow);
        }
      }
    }
    // Base pedestal stones
    fillRect(data, 7, 26, 18, 3, archDark);
    fillRect(data, 9, 26, 14, 1, archRunic);
    return { width: 32, height: 32, data };
  }

  /**
   * 32x32 Spike Trap overlay sprite ('trap_spike') with recessed iron plate slots and 5 crimson-tipped spikes.
   */
  private createSpikeTrapBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const plateBorder: RGBA = [24, 28, 38, 255];
    const plateBase: RGBA = [54, 61, 78, 255];
    const slotHole: RGBA = [16, 18, 26, 255];
    const spikeShadow: RGBA = [120, 132, 154, 255];
    const spikeSteel: RGBA = [206, 218, 236, 255];
    const spikeTipCrimson: RGBA = [220, 38, 38, 255];

    // Recessed iron pressure plate (transparent outer margin so floor stone shows around it)
    fillRect(data, 5, 11, 22, 16, plateBorder);
    fillRect(data, 6, 12, 20, 14, plateBase);
    // Corner rivets
    setPixel(data, 7, 13, spikeSteel);
    setPixel(data, 24, 13, spikeSteel);
    setPixel(data, 7, 24, spikeSteel);
    setPixel(data, 24, 24, spikeSteel);

    const drawSpike = (cx: number, baseY: number, height: number): void => {
      fillRect(data, cx - 2, baseY, 5, 2, slotHole);
      for (let h = 0; h < height; h++) {
        const y = baseY - h;
        if (h < 3) {
          setPixel(data, cx - 1, y, spikeShadow);
          setPixel(data, cx, y, spikeSteel);
          setPixel(data, cx + 1, y, spikeShadow);
        } else if (h < height - 2) {
          setPixel(data, cx, y, spikeSteel);
          setPixel(data, cx - 1, y, spikeShadow);
        } else {
          setPixel(data, cx, y, spikeTipCrimson);
        }
      }
    };

    // Back row of 3 spikes + front row of 2 spikes
    drawSpike(9, 17, 9);
    drawSpike(16, 16, 10);
    drawSpike(23, 17, 9);
    drawSpike(12, 23, 9);
    drawSpike(20, 23, 9);

    return { width: 32, height: 32, data };
  }

