  /**
   * 32x32 Teleport Trap overlay sprite ('trap_teleport') with glowing cyan-violet arcane sigil rings and runes.
   */
  private createTeleportTrapBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outerViolet: RGBA = [139, 92, 246, 235];
    const innerCyan: RGBA = [56, 189, 248, 250];
    const coreBright: RGBA = [224, 242, 254, 255];
    const plateSubtle: RGBA = [42, 34, 78, 190];

    for (let y = 5; y <= 26; y++) {
      for (let x = 5; x <= 26; x++) {
        const dx = x - 15.5;
        const dy = y - 15.5;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist <= 10.2 && dist >= 8.6) {
          setPixel(data, x, y, outerViolet);
        } else if (dist < 8.6 && dist >= 5.2) {
          if (Math.abs(Math.abs(dx) - Math.abs(dy)) < 0.9 || Math.abs(dx) < 0.8 || Math.abs(dy) < 0.8) {
            setPixel(data, x, y, innerCyan);
          } else {
            setPixel(data, x, y, plateSubtle);
          }
        } else if (dist < 5.2 && dist >= 3.6) {
          setPixel(data, x, y, innerCyan);
        } else if (dist < 2.2) {
          setPixel(data, x, y, coreBright);
        }
      }
    }

    return { width: 32, height: 32, data };
  }

  /**
   * 32x32 Magic Trap overlay sprite ('trap_magic') with a crimson-magenta cursed hexagram seal and gold rune nodes.
   */
  private createMagicTrapBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const darkCrimson: RGBA = [88, 22, 56, 215];
    const curseMagenta: RGBA = [236, 72, 153, 250];
    const hexCrimson: RGBA = [225, 29, 72, 255];
    const runeGold: RGBA = [251, 191, 36, 255];

    // Outer hexagonal seal ring & inner intersecting hexagram lines
    for (let y = 5; y <= 26; y++) {
      for (let x = 5; x <= 26; x++) {
        const dx = x - 15.5;
        const dy = y - 15.5;
        const hexDist = Math.max(Math.abs(dx), Math.abs(dx) * 0.5 + Math.abs(dy) * 0.866);
        if (hexDist <= 10.2 && hexDist >= 8.7) {
          setPixel(data, x, y, hexCrimson);
        } else if (hexDist < 8.7) {
          // Upward & downward equilateral triangle edges forming a hexagram
          const upTri =
            (Math.abs(dy - 4.5) < 0.85 && Math.abs(dx) <= 7.5) ||
            (dy >= -7.5 && dy <= 4.8 && Math.abs(Math.abs(dx) - (dy + 7.5) * 0.58) < 0.8);
          const downTri =
            (Math.abs(dy + 4.5) < 0.85 && Math.abs(dx) <= 7.5) ||
            (dy <= 7.5 && dy >= -4.8 && Math.abs(Math.abs(dx) - (7.5 - dy) * 0.58) < 0.8);
          if (upTri || downTri) {
            setPixel(data, x, y, curseMagenta);
          } else if (hexDist < 2.2) {
            setPixel(data, x, y, runeGold);
          } else if ((x + y) % 2 === 0) {
            setPixel(data, x, y, darkCrimson);
          }
        }
      }
    }
    // 6 golden hexagram vertex sparks
    setPixel(data, 16, 6, runeGold);
    setPixel(data, 16, 25, runeGold);
    setPixel(data, 8, 11, runeGold);
    setPixel(data, 23, 11, runeGold);
    setPixel(data, 8, 20, runeGold);
    setPixel(data, 23, 20, runeGold);

    return { width: 32, height: 32, data };
  }

