  /**
   * 32x32 armor-shattering stinger thrust icon ('skill_pierce' / '穿刺').
   */
  private createSkillPierceBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outline: RGBA = [24, 20, 34, 255];
    const plateSteel: RGBA = [126, 142, 168, 255];
    const plateCrack: RGBA = [36, 42, 58, 255];
    const stingerGold: RGBA = [245, 179, 36, 255];
    const stingerBright: RGBA = [254, 240, 138, 255];
    const sparkWhite: RGBA = [255, 252, 236, 255];

    // Cracked shield/armor silhouette in background
    fillRect(data, 14, 6, 12, 18, outline);
    fillRect(data, 15, 7, 10, 16, plateSteel);
    for (let i = 0; i < 8; i++) {
      setPixel(data, 17 + Math.floor(i * 0.5), 9 + i * 2, plateCrack);
      setPixel(data, 18 + Math.floor(i * 0.5), 10 + i * 2, plateCrack);
    }

    // Diagonal golden stinger lance piercing from bottom-left to top-right
    for (let i = 0; i < 20; i++) {
      const px = 5 + i;
      const py = 25 - i;
      const half = i < 8 ? 2 : i < 15 ? 1 : 0;
      for (let d = -half; d <= half; d++) {
        const edge = Math.abs(d) === half && half > 0;
        setPixel(data, px + d, py, edge ? outline : i > 13 ? stingerBright : stingerGold);
      }
    }
    // Impact shatter sparks at armor breach point
    fillRect(data, 17, 13, 3, 3, sparkWhite);
    setPixel(data, 15, 11, stingerBright);
    setPixel(data, 21, 11, stingerBright);
    setPixel(data, 21, 17, stingerBright);

    return { width: 32, height: 32, data };
  }

