  /**
   * 32x32 giant dungeon Bee ('enemy_bee' / '蜜蜂') with translucent wings, black-and-gold abdomen, and stinger.
   */
  private createBeeEnemyBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outline: RGBA = [22, 18, 14, 255];
    const chitinBlack: RGBA = [40, 34, 30, 255];
    const stripeGold: RGBA = [245, 184, 28, 255];
    const stripeBright: RGBA = [254, 228, 92, 255];
    const wingGlow: RGBA = [208, 240, 255, 215];
    const wingEdge: RGBA = [118, 178, 218, 240];
    const eyeCrimson: RGBA = [225, 42, 56, 255];
    const stingerSteel: RGBA = [232, 238, 248, 255];

    // Translucent upper pair of buzzing wings
    for (let y = 5; y <= 13; y++) {
      for (let x = 7; x <= 25; x++) {
        const leftWing = (x - 11.5) * (x - 11.5) / 18 + (y - 9) * (y - 9) / 14;
        const rightWing = (x - 19.5) * (x - 19.5) / 18 + (y - 9) * (y - 9) / 14;
        if (leftWing <= 1.0 || rightWing <= 1.0) {
          const edge = (leftWing > 0.72 && leftWing <= 1.0) || (rightWing > 0.72 && rightWing <= 1.0);
          setPixel(data, x, y, edge ? wingEdge : wingGlow);
        }
      }
    }

    // Antennae & head (left-facing menace)
    setPixel(data, 6, 11, outline);
    setPixel(data, 7, 12, outline);
    setPixel(data, 9, 11, outline);
    setPixel(data, 9, 12, outline);
    fillRect(data, 6, 13, 6, 6, outline);
    fillRect(data, 7, 14, 4, 4, chitinBlack);
    fillRect(data, 7, 15, 2, 2, eyeCrimson);

    // Fuzzy golden thorax & striped abdomen
    for (let y = 13; y <= 23; y++) {
      for (let x = 11; x <= 25; x++) {
        const dx = (x - 18) / 7.2;
        const dy = (y - 18) / 5.2;
        const r = dx * dx + dy * dy;
        if (r <= 1.05) {
          if (r > 0.78) {
            setPixel(data, x, y, outline);
          } else {
            const isGoldBand = x <= 14 || (x >= 17 && x <= 18) || (x >= 21 && x <= 22);
            setPixel(data, x, y, isGoldBand ? (y <= 16 ? stripeBright : stripeGold) : chitinBlack);
          }
        }
      }
    }

    // Rear venomous stinger tip & dangling legs
    fillRect(data, 25, 18, 4, 2, outline);
    fillRect(data, 26, 18, 3, 1, stingerSteel);
    setPixel(data, 12, 23, outline);
    setPixel(data, 11, 24, outline);
    setPixel(data, 16, 24, outline);
    setPixel(data, 15, 25, outline);
    setPixel(data, 20, 24, outline);

    return { width: 32, height: 32, data };
  }

