import { Actor } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { Point } from '../types';
import { Action, ActionResult } from './Action';

/**
 * Executes a Magic Skill (`'clever'`, `'fireball'`, etc.) performed by an `Enemy` (or non-player `Actor`)
 * toward `targetPos` via `world.executeEnemyMagicSkill`.
 */
export class MagicSkillAction implements Action {
  public readonly type = 'magic_skill';
  public readonly targetPos: Point;
  public readonly skillId: string;

  constructor(targetPos: Point, skillId: string) {
    this.targetPos = { ...targetPos };
    this.skillId = skillId;
  }

  public execute(caster: Actor, world: GameWorld): ActionResult {
    return world.executeEnemyMagicSkill(caster, this.targetPos, this.skillId);
  }
}
