export type EnemyDeserializer = (data: SerializedEnemy) => Enemy;
export type EnemySpawnFactory = (id: string, position: Point) => Enemy;

export interface NaturalSpawnEnemyEntry {
  readonly archetypeId: string;
  readonly level: number;
  readonly create: EnemySpawnFactory;
}

export interface FloorEnemySpawnProbability {
  readonly archetypeId: string;
  readonly level: number;
  readonly weight: number;
  readonly probability: number;
}

export interface WizardEnemyDescriptor {
  readonly archetypeId: string;
  readonly name: string;
  readonly spriteKey: string;
  readonly level: number;
  readonly xpReward: number;
  readonly dropsMeat: boolean;
  readonly meatSatietyValue: number;
  readonly meatWeight: number;
  readonly create: EnemySpawnFactory;
}

const enemyDeserializerRegistry = new Map<string, EnemyDeserializer>();
const enemySpawnFactoryRegistry = new Map<string, EnemySpawnFactory>();
const naturalSpawnRegistry = new Map<string, NaturalSpawnEnemyEntry>();

/**
 * Computes the unnormalized spawn weight of an enemy with `enemyLevel` on `effectiveFloor`:
 * w(enemy, F_eff) = 1 / (1 + (enemyLevel - F_eff)^2)
 */
export function computeEnemyFloorSpawnWeight(enemyLevel: number, effectiveFloor: number): number {
  const diff = enemyLevel - effectiveFloor;
  return 1 / (1 + diff * diff);
}

/**
 * Registers an enemy archetype into the natural dungeon spawn pool (`createWeightedEnemy`).
 */
export function registerNaturalSpawnEnemy(entry: NaturalSpawnEnemyEntry): void {
  naturalSpawnRegistry.set(entry.archetypeId, entry);
}

/**
 * Computes the normalized spawn probabilities across all natural dungeon enemies for `floorNumber` (`>= 1`),
 * clamping `effectiveFloor = min(floorNumber, maxRegisteredEnemyLevel + 1)` so deep floors keep higher-level
 * threats dominant until even higher-level monsters are added.
 */
export function getFloorEnemySpawnProbabilities(floorNumber = 1): FloorEnemySpawnProbability[] {
  const entries = Array.from(naturalSpawnRegistry.values());
  if (entries.length === 0) {
    return [];
  }
  const safeFloor = Math.max(1, Math.floor(floorNumber));
  let maxEnemyLevel = 1;
  const levelCounts = new Map<number, number>();
  for (const entry of entries) {
    if (entry.level > maxEnemyLevel) {
      maxEnemyLevel = entry.level;
    }
    levelCounts.set(entry.level, (levelCounts.get(entry.level) ?? 0) + 1);
  }
  const effectiveFloor = Math.min(safeFloor, maxEnemyLevel + 1);

  let totalWeight = 0;
  const weighted = entries.map((entry) => {
    const countAtLevel = Math.max(1, levelCounts.get(entry.level) ?? 1);
    const weight = computeEnemyFloorSpawnWeight(entry.level, effectiveFloor) / countAtLevel;
    totalWeight += weight;
    return { entry, weight };
  });

  return weighted.map(({ entry, weight }) => ({
    archetypeId: entry.archetypeId,
    level: entry.level,
    weight,
    probability: totalWeight > 0 ? weight / totalWeight : 1 / entries.length,
  }));
}

/**
 * Floor-aware weighted factory for spawning a natural dungeon enemy instance (`roll` in `[0, 1)`):
 * Weights each registered natural enemy by `1 / (1 + (enemy.level - effectiveFloor)^2)`.
 */
export function createWeightedEnemy(
  id: string,
  position: Point,
  roll: number,
  floorNumber = 1
): Enemy {
  const entries = Array.from(naturalSpawnRegistry.values());
  if (entries.length === 0) {
    return new Chick({ id, position });
  }
  const probs = getFloorEnemySpawnProbabilities(floorNumber);
  const clampedRoll = Math.max(0, Math.min(0.999999999, roll));

  let cumulative = 0;
  for (let i = 0; i < probs.length; i++) {
    cumulative += probs[i].probability;
    if (clampedRoll < cumulative || i === probs.length - 1) {
      const target = naturalSpawnRegistry.get(probs[i].archetypeId) ?? entries[entries.length - 1];
      return target.create(id, position);
    }
  }
  return entries[entries.length - 1].create(id, position);
}

function buildStubSerializedEnemy(archetypeId: string, id: string, position: Point): SerializedEnemy {
  return {
    archetypeId,
    sensingRange: DEFAULT_ENEMY_SENSING_RANGE,
    canOpenDoors: false,
    scoreValue: DEFAULT_ENEMY_SCORE_VALUE,
    dropsMeat: true,
    meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
    meatSatietyValue: DEFAULT_ENEMY_MEAT_SATIETY,
    meatWeight: DEFAULT_ENEMY_MEAT_WEIGHT,
    actorState: {
      id,
      name: archetypeId,
      spriteKey: archetypeId,
      position: { ...position },
      level: 1,
      xp: 0,
      baseAttributes: { str: 10, con: 10, int: 10, wis: 10, agi: 10, luk: 10 },
      attributeBonuses: {},
      attributeXp: { str: 0, con: 0, int: 0, wis: 0, agi: 0, luk: 0 },
      growthConfig: { base: 10, slope: 6 },
      enableAttributeGrowth: false,
      hp: 10,
      mp: 0,
      sp: 100,
      sightRadius: 6,
      nextActionTime: 0,
      lastActionSpRegenMultiplier: 1,
      hpRegenAccumulator: 0,
      mpRegenAccumulator: 0,
      spRegenAccumulator: 0,
      inventory: [],
    },
  };
}

/**
 * Registers a concrete Enemy subclass deserializer under its `archetypeId`.
 * Future enemy classes only need to register here to gain full Save/Load support
 * AND automatic discovery in developer Wizard Mode.
 */
export function registerEnemyDeserializer(
  archetypeId: string,
  deserializer: EnemyDeserializer,
  spawnFactory?: EnemySpawnFactory
): void {
  enemyDeserializerRegistry.set(archetypeId, deserializer);
  enemySpawnFactoryRegistry.set(
    archetypeId,
    spawnFactory ?? ((id, position) => deserializer(buildStubSerializedEnemy(archetypeId, id, position)))
  );
}

/**
 * Returns auto-discovered metadata and spawn factories for all registered enemy archetypes.
 */
export function getRegisteredWizardEnemies(): WizardEnemyDescriptor[] {
  const entries: WizardEnemyDescriptor[] = [];
  for (const [archetypeId, create] of enemySpawnFactoryRegistry.entries()) {
    const sample = create(`sample_${archetypeId}`, { x: 0, y: 0 });
    entries.push({
      archetypeId,
      name: sample.name,
      spriteKey: sample.spriteKey,
      level: sample.level,
      xpReward: sample.xpReward,
      dropsMeat: sample.dropsMeat,
      meatSatietyValue: sample.meatSatietyValue,
      meatWeight: sample.meatWeight,
      create,
    });
  }
  return entries;
}

/**
 * Reconstructs a concrete `Enemy` subclass instance from `SerializedEnemy` data,
 * restoring its full Actor state (Level, HP, MP, SP, timeline timestamp, inventory, etc.).
 */
export function deserializeEnemy(data: SerializedEnemy): Enemy {
  const factory = enemyDeserializerRegistry.get(data.archetypeId);
  let enemy: Enemy;
  if (factory) {
    enemy = factory(data);
  } else {
    enemy = new Enemy({
      id: data.actorState.id,
      archetypeId: data.archetypeId,
      name: data.actorState.name,
      position: { ...data.actorState.position },
      spriteKey: data.actorState.spriteKey,
      level: data.actorState.level ?? 1,
      xpReward: data.xpReward,
      sensingRange: data.sensingRange,
      canOpenDoors: data.canOpenDoors,
      avoidsTraps: data.avoidsTraps,
      scoreValue: data.scoreValue,
      dropsMeat: data.dropsMeat,
      meatDropChance: data.meatDropChance,
      meatSatietyValue: data.meatSatietyValue,
      meatWeight: data.meatWeight,
      attributes: data.actorState.baseAttributes,
      stats: data.actorState.customStatOverrides,
    });
  }
  enemy.restoreActorSaveState(data.actorState);
  if (typeof data.alertedTurns === 'number' && data.alertedTurns > 0) {
    enemy.setAlertedTurns(data.alertedTurns);
  }
  return enemy;
}

