import { Actor, PrimaryAttributeKey } from '../entities/Actor';
import { SeededRNG } from '../SeededRNG';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export const GROWTH_ELIGIBLE_ATTRIBUTES: readonly PrimaryAttributeKey[] = [
  'str',
  'con',
  'int',
  'wis',
  'agi',
];

export interface GrowthPotionOptions extends PotionItemOptions {}

/**
 * Potion of Growth (`成長藥水`): permanently increases 1 randomly chosen primary attribute
 * (excluding LUK: STR, CON, INT, WIS, or AGI) by +1 and resets that attribute's training XP to 0.
 */
export class GrowthPotion extends PotionItem {
  constructor(options: GrowthPotionOptions) {
    super({
      id: options.id ?? `growth-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Growth',
      itemTypeId: 'growth_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        'A potent mutagenic elixir that permanently increases one random primary attribute (except LUK) by +1 and resets its training XP.',
    });
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '隨機主屬性 +1' : 'Random Stat +1';
  }

  public override applyQuaffEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult {
    const idx = rng
      ? rng.nextInt(0, GROWTH_ELIGIBLE_ATTRIBUTES.length - 1)
      : Math.floor(Math.random() * GROWTH_ELIGIBLE_ATTRIBUTES.length);
    const chosenAttr = GROWTH_ELIGIBLE_ATTRIBUTES[idx];

    if (!target.isAlive()) {
      const current = target.baseAttributes[chosenAttr];
      return {
        kind: 'growth',
        observableEffect: false,
        grownAttribute: chosenAttr,
        oldValue: current,
        newValue: current,
      };
    }

    const { oldValue, newValue } = target.growAttributeAndResetXp(chosenAttr, 1);
    return {
      kind: 'growth',
      observableEffect: newValue > oldValue,
      grownAttribute: chosenAttr,
      oldValue,
      newValue,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): GrowthPotion {
    const cloned = new GrowthPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }
}

registerPotionType('growth_potion');
