import { Honey } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface BeeOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Bee (`蜜蜂`):
 * - Level 2 agile flying dungeon insect (`movementType = 'flying'`) that skims across shallow water
 *   and ignores ground pressure traps (`Spike`, `Pitfall`).
 * - Attacks adjacent targets with 70% Melee / 30% `Pierce` (`穿刺`, 40% chance to inflict `Armor Break`).
 * - Independent death drops: 20% `Meat of Bee`, 10% non-perishable `Honey`, and 5% `Pierce` Soul.
 */
export class Bee extends Enemy {
  constructor(options: BeeOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_bee',
      name: 'Bee',
      position: options.position,
      spriteKey: 'enemy_bee',
      level: 2,
      xpReward: 25,
      movementType: 'flying',
      sensingRange: 6,
      canOpenDoors: false,
      scoreValue: 60,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 100,
      meatWeight: 1.0,
      soulDropId: 'pierce',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      warSkills: [{ skillId: 'pierce', chance: 0.3 }],
      trophyDrops: [
        {
          itemTypeId: 'honey',
          chance: 0.1,
          create: ({ id, position }) => new Honey({ id, position }),
        },
      ],
      attributes: {
        str: 7,
        con: 5,
        int: 2,
        wis: 4,
        agi: 15,
        luk: 8,
      },
    });
  }
}
